import sys
s=sys.stdin.readline().rstrip("\n")
st=[];pair={')':'(',']':'[','}':'{'}
ok=True
for c in s:
    if c in '([{': st.append(c)
    else:
        if not st or st[-1]!=pair.get(c): ok=False;break
        st.pop()
if st: ok=False
print("valid" if ok else "invalid")

